CREATE TABLE IF NOT EXISTS "daily_plan_items" ("id" TEXT NOT NULL, "plan_id" TEXT NOT NULL REFERENCES daily_plans(id) ON DELETE CASCADE, "todo_item_id" TEXT NULL REFERENCES todo_items(id) ON DELETE CASCADE, "project_task_id" TEXT NULL REFERENCES tasks(id) ON DELETE CASCADE, "sort_order" INTEGER NOT NULL DEFAULT 0, "planned_minutes" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"),     CHECK (
      (todo_item_id IS NOT NULL AND project_task_id IS NULL)
      OR
      (todo_item_id IS NULL AND project_task_id IS NOT NULL)
    )
    , CHECK (planned_minutes IS NULL OR planned_minutes > 0));

CREATE TABLE IF NOT EXISTS "task_schedule_blocks" ("id" TEXT NOT NULL, "todo_item_id" TEXT NULL REFERENCES todo_items(id) ON DELETE CASCADE, "project_task_id" TEXT NULL REFERENCES tasks(id) ON DELETE CASCADE, "start_at" INTEGER NOT NULL, "end_at" INTEGER NOT NULL, "timezone_id" TEXT NULL, "block_kind" TEXT NOT NULL DEFAULT 'work', "note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"),     CHECK (
      (todo_item_id IS NOT NULL AND project_task_id IS NULL)
      OR
      (todo_item_id IS NULL AND project_task_id IS NOT NULL)
    )
    , CHECK (end_at > start_at), CHECK (block_kind IN ('work', 'focus', 'buffer')), CHECK (sort_order >= 0));
